with eligible as (select s.* from departments s where exists (select 1 from employees ch where ch.dept_id = s.id and lower(ch.full_name) like '%im %')), latest_match as (select s.*, x.employee_hire_date, x.level from eligible s left join lateral (select c.hire_date as employee_hire_date, c.level from employees c where c.dept_id = s.id order by c.hire_date desc, c.id desc limit 1) x on true), kept as (select s.* from latest_match s where exists (select 1 from employees ch where ch.dept_id = s.id and ch.hire_date >= s.employee_hire_date)), cleaned as (select id, dept_name, location, employee_hire_date, level, lower(location) as location_lower, floor(budget) as budget_whole from kept where budget is not null), deduped as (select id, dept_name, level, location_lower from (select *, row_number() over (partition by location order by employee_hire_date desc, id) as rank_in_group from cleaned) x where rank_in_group = 1) select level, dept_name, count(case when level = 'L1' then 1 end) as l1_count, sort_array(collect_set(level)) as level_list, sort_array(collect_set(dept_name)) as dept_name_list, dense_rank() over (partition by level order by count(case when level = 'L1' then 1 end) desc) as l1_count_dense_rank from deduped group by level, dept_name;
